function nonce() { return [...Array(32)].map(() => Math.floor(Math.random() * 36).toString(36)).join(''); }

function sourceScan(session) {
  const sources = (session.sourcePaths || []).map((filename) => {
    const document = vscode.workspace.textDocuments.find((item) => path.resolve(item.fileName) === path.resolve(filename));
    const stat = document ? null : fs.statSync(filename);
    return { filename, text: document ? document.getText() : fs.readFileSync(filename, 'utf8'), revision: document ? `open:${document.version}` : `disk:${stat.size}:${stat.mtimeMs}` };
  });
  const signature = sources.map((source) => `${source.filename}:${source.revision}`).join('|');
  if (session.sourceCache && session.sourceCache.signature === signature) return session.sourceCache;
  session.sourceCache = { signature, files: sources.map((source) => source.filename), findings: inspectSources(sources) };
  return session.sourceCache;
}

function clientModel(session, text) {
  const airDocument = vscode.workspace.textDocuments.find((item) => path.resolve(item.fileName) === path.resolve(session.airPath));
  const constantsDocument = session.constantsPath && vscode.workspace.textDocuments.find((item) => path.resolve(item.fileName) === path.resolve(session.constantsPath));
  const constantsText = session.constantsPath ? constantsDocument ? constantsDocument.getText() : fs.readFileSync(session.constantsPath, 'utf8') : '';
  const scan = sourceScan(session);
  const parsedActions = parseAir(text), sourceLines = text.split(/\r?\n/);
  const actions = parsedActions.map((action, sourceOrder) => ({
    ...action, sourceText: sourceLines.slice(action.line - 1, (parsedActions[sourceOrder + 1]?.line || sourceLines.length + 1) - 1).join('\n'), sourceOrder, category: animationCategory(action.number), ...systemName(action.number),
    frames: action.frames.map((frame) => ({ ...frame, spriteMissing: frame.group >= 0 && !session.byKey.has(`${frame.group},${frame.index}`) }))
  }));
  return {
    title: path.basename(session.airPath), airPath: session.airPath, sffPath: session.sffPath,
    initialAction: session.initialAction, actions, missingSpriteFrames: actions.reduce((sum, action) => sum + action.frames.filter((frame) => frame.spriteMissing).length, 0), palettes: session.archive.palettes.map((palette) => ({ index: palette.index, group: palette.group, number: palette.number })), palettePreview: previewPreferences(session.archive, session.sffPath || session.airPath, 'air'),
    pushboxes: parseSizeboxes(constantsText), pushOverrides: readPushboxPlan(session.airPath).overrides,
    runtimeDefaults: parseRuntimeDefaults(constantsText), runtimeEntries: readRuntimePlan(session.airPath).entries, runtimeDrafts: runtimeDraftStore.read(session.airPath),
    sourceFiles: scan.files, sourceFindings: scan.findings,
    experience: workspaceExperience('air', mode('assets', vscode.Uri.file(session.airPath))),
    sourceState: sourceState(airDocument, path.basename(session.airPath))
  };
}

