  try { const data = JSON.parse(result.stdout || '{}'), delaysMs = (data.frames || []).map((frame) => Math.round(Number(frame.pkt_duration_time || 0) * 1000)); return { frameCount: Number(data.streams?.[0]?.nb_frames) || delaysMs.length, delaysMs }; } catch (_) { return { frameCount: 0, delaysMs: [] }; }
